+const ModelOptions = z.object({
+  apiKey: z.string().refine((key) => key.trim().length > 0, "An injected Anthropic API key is required."),
+  modelId: z.string().trim().min(1).refine(
+    (id) => !id.includes("/") || /^anthropic\/[^/\s]+$/.test(id),
+    "Only a bare Anthropic model ID or anthropic/model ID is supported.",
+  ),
